// Отбор (пусто — без отбора): любая из сфер, город (без регистра; «Вся Россия» подходит любому), любой из форматов.
func (q *Queries) ListPublishedTasks(ctx context.Context, arg ListPublishedTasksParams) ([]ListPublishedTasksRow, error) {
	rows, err := q.db.Query(ctx, listPublishedTasks,
		arg.BeforeAt,
		arg.BeforeID,
		arg.Categories,
		arg.City,
		arg.Formats,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListPublishedTasksRow{}
	for rows.Next() {
		var i ListPublishedTasksRow
		if err := rows.Scan(
			&i.ID,
			&i.OwnerID,
			&i.Status,
			&i.RejectReason,
			&i.Title,
			&i.City,
			&i.Nationwide,
			&i.Formats,
			&i.Access,
			&i.MinViews,
			&i.RewardKopecks,
			&i.PublishBy,
			&i.Blocks,
			&i.Cover,
			&i.Photos,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.SubmittedAt,
			&i.PublishedAt,
			&i.PublishTime,
			&i.DeadlineAt,
			&i.Categories,
			&i.ReviewNotes,
			&i.Revision,
			&i.RevisionStatus,
			&i.RevisionReason,
			&i.RevisionSubmittedAt,
			&i.Brand,
			&i.CategoryTitles,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

