type SubmitStatsSinceParams struct {
	ActorID pgtype.Int8
	Since   pgtype.Timestamptz
}

type SubmitStatsSinceRow struct {
	Sent    int32
	FirstAt pgtype.Timestamptz
}

func (q *Queries) SubmitStatsSince(ctx context.Context, arg SubmitStatsSinceParams) (SubmitStatsSinceRow, error) {
	row := q.db.QueryRow(ctx, submitStatsSince, arg.ActorID, arg.Since)
	var i SubmitStatsSinceRow
	err := row.Scan(&i.Sent, &i.FirstAt)
	return i, err
}

const updateOwnTask = `-- name: UpdateOwnTask :one
UPDATE tasks
SET title = $1, city = $2, nationwide = $3, categories = $4, formats = $5,
    access = $6, min_views = $7, reward_kopecks = $8,
    publish_by = $9, publish_time = $10, deadline_at = $11, blocks = $12, cover = $13, photos = $14, updated_at = now()
WHERE id = $15 AND owner_id = $16 AND status IN ('draft', 'rejected', 'changes_requested')
RETURNING id, owner_id, status, reject_reason, title, city, nationwide, formats, access, min_views, reward_kopecks, publish_by, blocks, cover, photos, created_at, updated_at, submitted_at, published_at, publish_time, deadline_at, categories, review_notes, revision, revision_status, revision_reason, revision_submitted_at
`

type UpdateOwnTaskParams struct {
	Title         string
	City          string
	Nationwide    bool
	Categories    []string
	Formats       []string
	Access        string
	MinViews      int64
	RewardKopecks int64
	PublishBy     pgtype.Date
	PublishTime   pgtype.Time
	DeadlineAt    pgtype.Timestamptz
	Blocks        []byte
	Cover         pgtype.Text
	Photos        []string
	ID            int64
	OwnerID       int64
}

// Правка — только черновика, отклонённого или возвращённого на доработку (статус проверяется в том же запросе:
// гонки с модерацией нет).
func (q *Queries) UpdateOwnTask(ctx context.Context, arg UpdateOwnTaskParams) (Task, error) {
	row := q.db.QueryRow(ctx, updateOwnTask,
		arg.Title,
		arg.City,
		arg.Nationwide,
		arg.Categories,
		arg.Formats,
		arg.Access,
		arg.MinViews,
		arg.RewardKopecks,
		arg.PublishBy,
		arg.PublishTime,
		arg.DeadlineAt,
		arg.Blocks,
		arg.Cover,
		arg.Photos,
		arg.ID,
		arg.OwnerID,
	)
	var i Task
	err := row.Scan(
		&i.ID,
		&i.OwnerID,
		&i.Status,
		&i.RejectReason,
		&i.Title,
		&i.City,
		&i.Nationwide,
		&i.Formats,
		&i.Access,
		&i.MinViews,
		&i.RewardKopecks,
		&i.PublishBy,
		&i.Blocks,
		&i.Cover,
		&i.Photos,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.SubmittedAt,
		&i.PublishedAt,
		&i.PublishTime,
		&i.DeadlineAt,
		&i.Categories,
		&i.ReviewNotes,
		&i.Revision,
		&i.RevisionStatus,
		&i.RevisionReason,
		&i.RevisionSubmittedAt,
	)
	return i, err
}

const upsertCard = `-- name: UpsertCard :one
INSERT INTO creator_cards (user_id, name, city, topics, platforms, blocks, avatar, works)
VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
ON CONFLICT (user_id) DO UPDATE
SET name = EXCLUDED.name, city = EXCLUDED.city, topics = EXCLUDED.topics, platforms = EXCLUDED.platforms,
    blocks = EXCLUDED.blocks, avatar = EXCLUDED.avatar, works = EXCLUDED.works, updated_at = now()
WHERE creator_cards.status IN ('draft', 'rejected', 'changes_requested')
RETURNING user_id, status, reject_reason, name, city, topics, platforms, blocks, avatar, works, created_at, updated_at, submitted_at, published_at, review_notes, revision, revision_status, revision_reason, revision_submitted_at
`

type UpsertCardParams struct {
	UserID    int64
	Name      string
	City      string
	Topics    []string
	Platforms []byte
	Blocks    []byte
	Avatar    pgtype.Text
	Works     []string
}

// Создать или обновить — только черновик, отклонённую или возвращённую на доработку.
func (q *Queries) UpsertCard(ctx context.Context, arg UpsertCardParams) (CreatorCard, error) {
	row := q.db.QueryRow(ctx, upsertCard,
		arg.UserID,
		arg.Name,
		arg.City,
		arg.Topics,
		arg.Platforms,
		arg.Blocks,
		arg.Avatar,
		arg.Works,
	)
	var i CreatorCard
	err := row.Scan(
		&i.UserID,
		&i.Status,
		&i.RejectReason,
		&i.Name,
		&i.City,
		&i.Topics,
		&i.Platforms,
		&i.Blocks,
		&i.Avatar,
		&i.Works,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.SubmittedAt,
		&i.PublishedAt,
		&i.ReviewNotes,
		&i.Revision,
		&i.RevisionStatus,
		&i.RevisionReason,
		&i.RevisionSubmittedAt,
	)
	return i, err
}
